//go:build amd64

package gf65536

import "golang.org/x/sys/cpu"

// Kernels generated by go-asmgen (gen/) into galois_amd64.s (SSSE3, 32-byte
// blocks) and galois_amd64_avx2.s (AVX2, 64-byte blocks). tbl is the 128-byte
// table built by buildSplitTables.
func galMulSSSE3(dst, src []byte, tbl *[128]byte, n int)
func galMulAddSSSE3(dst, src []byte, tbl *[128]byte, n int)
func galMulAVX2(dst, src []byte, tbl *[128]byte, n int)
func galMulAddAVX2(dst, src []byte, tbl *[128]byte, n int)

func archTiers() (t []tier) {
	if cpu.X86.HasAVX2 {
		t = append(t, tier{"avx2",
			func(dst, src []byte, tbl *[128]byte) int {
				n := len(src) &^ (blockBytes - 1)
				m := n &^ 63
				if m > 0 {
					galMulAVX2(dst[:m], src[:m], tbl, m/64)
				}
				if n > m {
					galMulSSSE3(dst[m:n], src[m:n], tbl, 1)
				}
				return n
			},
			func(dst, src []byte, tbl *[128]byte) int {
				n := len(src) &^ (blockBytes - 1)
				m := n &^ 63
				if m > 0 {
					galMulAddAVX2(dst[:m], src[:m], tbl, m/64)
				}
				if n > m {
					galMulAddSSSE3(dst[m:n], src[m:n], tbl, 1)
				}
				return n
			}})
	}
	if cpu.X86.HasSSSE3 {
		t = append(t, blockTier("ssse3", galMulSSSE3, galMulAddSSSE3))
	}
	return t
}
